package com.leotv.detail;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Bounded transparent cutouts from the two user-supplied decorative figures. */
final class DanmakuComicArt {
    static final int WIDTH=72,HEIGHT=112,PIXEL_BYTES=WIDTH*HEIGHT*4;
    private static final String[] PNG={
        "",
        ""};
    static Bitmap decode(int variant){byte[] bytes=Base64.decode(PNG[variant&1],Base64.DEFAULT);BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap!=null)bitmap.setDensity(Bitmap.DENSITY_NONE);return bitmap;}
    private DanmakuComicArt(){}
}
